```c
// utf8.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int validate_utf8(const uint8_t* data, size_t len, char** errorMsg) {
    *errorMsg = NULL;

    for (size_t i = 0; i < len; i++) {
        if (data[i] <= 0x7F) continue;

        int bytes = 0;
        if ((data[i] & 0xE0) == 0xC0) bytes = 2;
        else if ((data[i] & 0xF0) == 0xE0) bytes = 3;
        else if ((data[i] & 0xF8) == 0xF0) bytes = 4;
        else {
            *errorMsg = malloc(64);
            snprintf(*errorMsg, 64, "Invalid UTF-8 start byte 0x%02X at position %zu", data[i], i);
            return -1;
        }

        if (i + bytes > len) {
            *errorMsg = malloc(64);
            snprintf(*errorMsg, 64, "Truncated UTF-8 sequence at position %zu", i);
            return -1;
        }

        for (int j = 1; j < bytes; j++) {
            if ((data[i + j] & 0xC0) != 0x80) {
                *errorMsg = malloc(64);
                snprintf(*errorMsg, 64, "Invalid continuation byte 0x%02X at position %zu", data[i + j], i + j);
                return -1;
            }
        }
        i += bytes - 1;
    }
    return 0;
}
```

```go
// utf8.go
package main

// #cgo CFLAGS: -.
// #include "utf8.h"
import "C"
import (
	"errors"
	"sync"
)

func ValidateUTF8(data []byte) (bool, string, error) {
	var errMsg *C.char
	result := C.validate_utf8((*C.uint8_t)(&data[0]), C.size_t(len(data)), &errMsg)

	if result == 0 {
		return true, "", nil
	}

	msg := C.GoString(errMsg)
	C.free(unsafe.Pointer(errMsg))
	return false, msg, errors.New(msg)
}

func ValidateUTF8Concurrently(buffers ...[]byte) []struct {
	valid  bool
	msg    string
	err    error
	wg     *sync.WaitGroup
} {
	var wg sync.WaitGroup
	results := make([]struct {
		valid bool
		msg   string
		err   error
		wg   *sync.WaitGroup
	}, len(buffers))

	for i, buf := range buffers {
		wg.Add(1)
		results[i].wg = &wg
		go func(data []byte, idx int) {
			valid, msg, err := ValidateUTF8(data)
			results[idx].valid = valid
			results[idx].msg = msg
			results[idx].err = err
			wg.Done()
		}(buf, i)
	}

	wg.Wait()
	return results
}

func main() {
	buffer1 := []byte("Hello, World!")
	buffer2 := []byte{0xFF, 0xFE, 0x55}

	results := ValidateUTF8Concurrently(buffer1, buffer2)

	for i, r := range results {
		fmt.Printf("Buffer %d: valid=%v, msg=%s\n", i+1, r.valid, r.msg)
	}
}
```

